import Foundation

/// Loads the bundled airport files and answers questions about them:
/// "which airport is SFO?", "what's near me?", "what matches 'san fr'?".
///
/// - `airports.json` is generated by `scripts/build_airports.py` from OurAirports data.
/// - `featured_airports.json` is a hand-edited list of famous codes the
///   Check-in screen prefers to suggest. Add or remove codes freely.
nonisolated struct AirportStore: Sendable {
    let airports: [Airport]
    let featuredCodes: Set<String>
    private let byCode: [String: Airport]

    init(airports: [Airport], featuredCodes: Set<String> = []) {
        self.airports = airports
        self.featuredCodes = featuredCodes
        // A dictionary gives instant lookup by code instead of scanning 1,000+ airports.
        self.byCode = Dictionary(airports.map { ($0.iata, $0) },
                                 uniquingKeysWith: { first, _ in first })
    }

    /// Reads both JSON files from the app bundle (the files shipped inside the app).
    static func loadBundled(from bundle: Bundle = .main) throws -> AirportStore {
        // JSONDecoder matches JSON keys to Airport's property names — that's what Codable buys us.
        let airports = try decode([Airport].self, named: "airports", in: bundle)
        let featured = try decode([String].self, named: "featured_airports", in: bundle)
        return AirportStore(airports: airports, featuredCodes: Set(featured))
    }

    private static func decode<T: Decodable>(_ type: T.Type, named name: String, in bundle: Bundle) throws -> T {
        guard let url = bundle.url(forResource: name, withExtension: "json") else {
            throw LoadError.fileMissing(name)
        }
        return try JSONDecoder().decode(type, from: Data(contentsOf: url))
    }

    func airport(code: String) -> Airport? {
        byCode[code.uppercased()]
    }

    func isFeatured(_ airport: Airport) -> Bool {
        featuredCodes.contains(airport.iata)
    }

    /// The airports closest to a point, nearest first — for "use my location".
    func nearest(to point: Coordinate, limit: Int = 3) -> [NearbyAirport] {
        airports
            .map { NearbyAirport(airport: $0, distanceKm: GreatCircle.distanceKm(from: point, to: $0.coordinate)) }
            .sorted { $0.distanceKm < $1.distanceKm }
            .prefix(limit)
            .map { $0 }
    }

    /// Airports matching what someone typed, best matches first:
    /// exact code ("sfo") → city starts with ("san fr") → name or city contains ("kennedy").
    func search(_ query: String, limit: Int = 20) -> [Airport] {
        let q = query.trimmingCharacters(in: .whitespaces).lowercased()
        guard !q.isEmpty else { return [] }

        func rank(_ a: Airport) -> Int? {
            if a.iata.lowercased() == q { return 0 }
            if a.city.lowercased().hasPrefix(q) { return 1 }
            if a.name.lowercased().contains(q) || a.city.lowercased().contains(q) { return 2 }
            return nil
        }

        return airports
            .compactMap { a in rank(a).map { (a, $0) } }
            // Same rank? Famous airports first, then alphabetical by city.
            .sorted { lhs, rhs in
                if lhs.1 != rhs.1 { return lhs.1 < rhs.1 }
                let lf = isFeatured(lhs.0), rf = isFeatured(rhs.0)
                if lf != rf { return lf }
                return lhs.0.city < rhs.0.city
            }
            .prefix(limit)
            .map(\.0)
    }

    enum LoadError: Error {
        case fileMissing(String)
    }
}

/// An airport plus how far it is from you.
nonisolated struct NearbyAirport: Identifiable, Hashable, Sendable {
    let airport: Airport
    let distanceKm: Double
    var id: String { airport.id }
}
